const extraKey='godzilla-archive-catalog-v3';
let additions={films:[],kaijus:[],edits:{}};try{const d=JSON.parse(localStorage.getItem(extraKey)||'{}');if(d&&typeof d==='object')additions={films:Array.isArray(d.films)?d.films:[],kaijus:Array.isArray(d.kaijus)?d.kaijus:[],edits:d.edits||{}}}catch{}
// Migrate legacy built-in kaiju IDs in user-edited film links without deleting personal edits.
const legacyKaijuAliases={"godzilla-monsterverse":"godzilla-mv","shin":"godzilla-shin","minus":"godzilla-minus","rodan":"rodan-showa","mothra":"mothra-showa","king-ghidorah":"ghidorah-showa","anguirus":"anguirus-showa","mechagodzilla":"mecha-showa"};
for(const edit of Object.values(additions.edits)){
 if(edit&&Array.isArray(edit.kaiju))edit.kaiju=[...new Set(edit.kaiju.map(id=>legacyKaijuAliases[id]||id))];
}
const films=[...baseFilms,...additions.films].map(f=>({...f,...(additions.edits[f.id]||{})}));
const kaijus=[...baseKaijus,...additions.kaijus].map(k=>({...k,...(additions.edits[k.id]||{})}));
// V5: asociaciones derivadas de las fichas de kaijus, sin sobrescribir ediciones personales.
for(const f of films){
  if(Object.prototype.hasOwnProperty.call(additions.edits,f.id)&&Object.prototype.hasOwnProperty.call(additions.edits[f.id],'kaiju'))continue;
  const ids=kaijus.filter(k=>Array.isArray(k.films)&&k.films.includes(f.id)).map(k=>k.id);
  f.kaiju=[...new Set([...(Array.isArray(f.kaiju)?f.kaiju:[]),...ids].map(id=>legacyKaijuAliases[id]||id))];
}
const eraProgress=e=>{const fs=films.filter(f=>f.era===e);const seen=fs.filter(f=>rec(f.id).watched).length;return {seen,total:fs.length,percent:fs.length?Math.round(seen/fs.length*100):0}};
const saveCatalog=()=>localStorage.setItem(extraKey,JSON.stringify(additions));
