function outsideCards(k){const titles=k.outside||[];if(!titles.length)return '<p class="muted">Sin apariciones externas documentadas en esta ficha.</p>';return `<div class="outside-grid">${titles.map((t,i)=>`<article class="outside-card"><div class="outside-poster art" data-outside-title="${esc(t)}" aria-label="Póster de ${esc(t)}"><span>映画</span></div><strong>${esc(t)}</strong><small>Fuera de la franquicia Godzilla</small></article>`).join('')}</div>`}
const outsideCache={};
async function hydrateOutside(){for(const el of app.querySelectorAll('[data-outside-title]')){const title=el.dataset.outsideTitle;const wiki=outsideTitles[title];if(!wiki)continue;try{if(!(title in outsideCache)){const r=await fetch('https://en.wikipedia.org/api/rest_v1/page/summary/'+encodeURIComponent(wiki));const d=r.ok?await r.json():{};outsideCache[title]=d.thumbnail?.source||''}if(el.isConnected&&outsideCache[title]){el.style.backgroundImage=`linear-gradient(0deg,rgba(10,10,10,.24),transparent 70%),url("${outsideCache[title]}")`;el.classList.add('has-image')}}catch{}}}
function kaijuCard(k){return `<article class="card kaiju-card" data-kaiju="${k.id}"><div class="kaiju-art art" data-image-key="kaiju:${k.id}"><span>怪獣</span></div><div><strong>${esc(k.name)}</strong><small>${esc(k.kind)}</small><small>${k.films.length} apariciones registradas</small></div></article>`}
function uploadControl(key,label){return `<label class="upload-label">${esc(label)}<input class="image-upload" type="file" accept="image/*" data-upload-key="${esc(key)}"></label>`}
function attachUploads(){app.querySelectorAll('.image-upload').forEach(el=>el.onchange=async()=>{const file=el.files?.[0];if(!file)return;if(file.size>12*1024*1024){alert('Elige una imagen de menos de 12 MB.');return}try{await imagePut(el.dataset.uploadKey,file);render()}catch{alert('No se pudo guardar la imagen. Comprueba el espacio disponible en el navegador.')}})}
function render(){clearUrls();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));
if(selectedKaiju){const k=kaijus.find(x=>x.id===selectedKaiju);app.innerHTML=`<button class="secondary back" id="back">← Volver a kaijus</button><div class="detail-head"><div class="kaiju-hero art" data-image-key="kaiju:${k.id}"><span>怪獣</span></div><div><span class="tag">FICHA KAIJU</span><h2>${esc(k.name)}</h2><p><b>Tipo:</b> ${esc(k.kind)}</p><p>${esc(k.desc)}</p>${uploadControl('kaiju:'+k.id,'Añadir foto del kaiju')}</div></div><h3>Interpretación y efectos</h3><p>${performerText(k)}</p>${performerPortraits(k)}<h3>Apariciones en películas</h3><div class="grid">${films.filter(f=>k.films.includes(f.id)).map(card).join('')}</div><h3>Otras apariciones (fuera de Godzilla)</h3>${outsideCards(k)}<h3>Trajes, diseños y versiones</h3><p class="muted">Cuando una película utiliza CGI, se indica en lugar de atribuirle un traje físico.</p><div class="suit-grid">${k.suits.map((s,i)=>`<section class="card suit"><div class="suit-art art" data-image-key="suit:${k.id}:${i}"><span>DESIGN ${i+1}</span></div><strong>${esc(s[0])}</strong><small>${esc(s[1])}</small><small class="photo-status">Fotografía no disponible · buscando diseño</small>${uploadControl(`suit:${k.id}:${i}`,'Añadir foto del diseño')}</section>`).join('')}</div>`;document.getElementById('back').onclick=()=>{selectedKaiju=null;render()};}
else if(selected){const f=films.find(x=>x.id===selected),r=rec(f.id);app.innerHTML=`<button class="secondary back" id="back">← Volver</button><div class="detail-head"><div><div class="detail-poster art" data-image-key="poster:${f.id}:${filmPosterIndex}"><span>${esc(f.title)}</span><small>${f.year} · ${esc(f.era)}</small></div><div class="poster-controls"><button class="secondary" id="prevPoster">‹</button><span>Póster ${filmPosterIndex+1} / 5</span><button class="secondary" id="nextPoster">›</button></div>${uploadControl(`poster:${f.id}:${filmPosterIndex}`,'Añadir o cambiar este póster')}</div><div><span class="tag">${esc(f.era)}</span><h2>${esc(f.title)} <span class="year">(${f.year})</span></h2><p><b>Dirección:</b> ${esc(f.director)}</p><p>${esc(f.desc)}</p><p class="muted"><b>Continuidad:</b> ${esc(f.continuity)}</p></div></div><section><h3>Kaijus de esta película</h3><div class="kaiju-list">${kaijus.filter(k=>f.kaiju.includes(k.id)).map(k=>`<button class="kaiju-chip" data-kaiju="${k.id}">${esc(k.name)} <span>→</span></button>`).join('')||'<p class="muted">Todavía no hay kaijus documentados para esta película.</p>'}</div></section><section class="card soundtrack"><h3>♪ Banda sonora</h3><p>Busca la música de esta película en Spotify.</p><a class="spotify" href="https://open.spotify.com/search/${encodeURIComponent(f.title+' soundtrack')}" target="_blank" rel="noopener noreferrer">♫ ESCUCHAR EN SPOTIFY ↗</a></section><section class="card register"><h3>Mi registro</h3><button id="watched" class="watch-button ${r.watched?'watched':''}" aria-pressed="${!!r.watched}">${r.watched?'✓ YA LA VI':'○ TODAVÍA NO LA VEO'}</button><button id="favorite" type="button" class="favorite-button ${r.favorite?'favorite-on':''}" aria-pressed="${!!r.favorite}">${r.favorite?'♥ EN MIS FAVORITAS':'♡ AÑADIR A FAVORITAS'}</button><label for="score">Mi puntuación (0–10)</label><div class="score-row"><input id="score" type="number" min="0" max="10" step="0.1" inputmode="decimal" placeholder="Ej. 8,5" value="${r.score??''}"><span>/ 10</span></div><details class="extra-rating"><summary>Puntuaciones por categorías (opcionales)</summary><div class="category-grid">${categories.map(([id,label])=>`<label>${label}<input class="category-score" data-category="${id}" type="number" min="0" max="10" step="0.1" inputmode="decimal" placeholder="0–10" value="${r.categories?.[id]??''}"></label>`).join('')}</div></details><label for="review">Mi opinión</label><textarea id="review" placeholder="Escribe tu reseña personal...">${esc(r.review||'')}</textarea><button class="primary" id="save">GUARDAR RESEÑA</button><div class="watch-history"><h3>Historial de visionados</h3><p class="muted small">Registra cada vez que vuelvas a ver esta película. Puedes añadir una nota diferente para cada visionado.</p><label for="watchdate">Fecha</label><input id="watchdate" type="date"><label for="watchnote">Nota de este visionado (opcional)</label><textarea id="watchnote" placeholder="¿Qué te pareció esta vez?"></textarea><button class="secondary" id="addwatch">+ REGISTRAR VISIONADO</button><div class="history-list">${(r.watches||[]).slice().reverse().map((w,i)=>`<div class="history-entry"><strong>${esc(w.date)}</strong><p>${esc(w.note||'Sin nota')}</p><button class="secondary remove-watch" data-index="${(r.watches||[]).length-1-i}">Eliminar</button></div>`).join('')||'<p class="muted">Todavía no has registrado fechas.</p>'}</div></div><p class="muted small">Tus registros se guardan en este navegador. Las imágenes que agregues se almacenan aparte.</p></section>`;
let favorite=!!r.favorite;const fav=document.getElementById('favorite');fav.onclick=()=>{favorite=!favorite;fav.classList.toggle('favorite-on',favorite);fav.textContent=favorite?'♥ EN MIS FAVORITAS':'♡ AÑADIR A FAVORITAS';fav.setAttribute('aria-pressed',String(favorite))};
const watchDate=document.getElementById('watchdate');watchDate.value=new Date().toLocaleDateString('en-CA');
document.getElementById('addwatch').onclick=()=>{const date=watchDate.value;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)){alert('Selecciona una fecha válida.');return}const prev=rec(f.id);records[f.id]={...prev,watches:[...(prev.watches||[]),{date,note:document.getElementById('watchnote').value}],watched:true};save();render()};
app.querySelectorAll('.remove-watch').forEach(btn=>btn.onclick=()=>{if(!confirm('¿Eliminar este visionado?'))return;const old=rec(f.id);const watches=[...(old.watches||[])];watches.splice(Number(btn.dataset.index),1);records[f.id]={...old,watches};save();render()});
let watched=!!r.watched;const w=document.getElementById('watched');w.onclick=()=>{watched=!watched;w.classList.toggle('watched',watched);w.textContent=watched?'✓ YA LA VI':'○ TODAVÍA NO LA VEO';w.setAttribute('aria-pressed',String(watched))};document.getElementById('back').onclick=()=>{selected=null;render()};document.getElementById('prevPoster').onclick=()=>{filmPosterIndex=(filmPosterIndex+4)%5;render()};document.getElementById('nextPoster').onclick=()=>{filmPosterIndex=(filmPosterIndex+1)%5;render()};document.getElementById('save').onclick=()=>{const raw=document.getElementById('score').value.trim().replace(',','.');const score=raw===''?undefined:Number(raw);if(raw!==''&&(!Number.isFinite(score)||score<0||score>10)){alert('Escribe una puntuación entre 0 y 10.');return}const cat={};for(const inp of app.querySelectorAll('.category-score')){const v=inp.value.trim().replace(',','.');if(v){const n=Number(v);if(!Number.isFinite(n)||n<0||n>10){alert('Las puntuaciones por categoría deben estar entre 0 y 10.');return}cat[inp.dataset.category]=n}}records[f.id]={...rec(f.id),watched,score,review:document.getElementById('review').value,favorite,categories:cat};save();render();alert('Reseña guardada')};}
else if(tab==='home'){const seen=films.filter(f=>rec(f.id).watched);app.innerHTML=`<div class="hero"><span class="hero-jp">ゴジラ・アーカイブ</span><h2>EL REY DE LOS MONSTRUOS</h2><p>Tu archivo personal de cine kaiju</p></div><div class="stats"><div class="stat"><strong>${seen.length}</strong><span>Vistas</span></div><div class="stat"><strong>${films.length-seen.length}</strong><span>Sin ver</span></div><div class="stat"><strong>${avg(films)}</strong><span>Mi promedio</span></div></div><h3>Promedio por era</h3><div class="era-stats">${eras.map(e=>{const p=eraProgress(e[0]);return `<div class="era-progress"><span>${e[0]}<small>${p.seen}/${p.total} vistas · ${p.percent}%</small><i class="progress-track"><b style="width:${p.percent}%"></b></i></span><strong>${avg(films.filter(f=>f.era===e[0]))} <small>/10</small></strong></div>`}).join('')}</div><p class="notice">Catálogo de 38 largometrajes hasta 2024. Sinopsis de las 38 películas incorporadas. Las fotografías online se muestran cuando hay una coincidencia plausible; los diseños sin foto muestran un aviso de imagen no disponible. Verifica los créditos y diseños antes de citar imágenes; las estadísticas usan tus registros.</p><h3>Explorar películas</h3><div class="grid">${films.slice(0,4).map(card).join('')}</div>`}
else if(tab==='films'){app.innerHTML=`<h2>CATÁLOGO</h2><p class="muted">Explora películas, pósteres, monstruos y tus reseñas.</p><input id="filter" placeholder="Buscar por título, año o era..."><div id="filmgrid" class="grid">${films.map(card).join('')}</div>`;document.getElementById('filter').oninput=e=>{const q=e.target.value.toLowerCase();document.getElementById('filmgrid').innerHTML=films.filter(f=>(f.title+' '+f.year+' '+f.era).toLowerCase().includes(q)).map(card).join('');bindFilms();hydrate()}}
else if(tab==='eras'){app.innerHTML=`<h2>ERAS Y CRONOLOGÍAS</h2><p class="muted">Mapa visual de las distintas continuidades. Desliza cada fila horizontalmente y toca un póster para abrir su película. Las líneas representan conexiones narrativas, no solo fechas de estreno.</p><div class="timeline-legend"><span>● Película original</span><span>━ Misma continuidad</span><span>↳ Nueva rama / reinicio</span></div>${timelineSections.map(section=>{const fs=section.ids.map(id=>films.find(f=>f.id===id)).filter(Boolean);return `<section class="timeline-section"><div class="timeline-heading"><div><span class="timeline-kicker">${esc(section.label)}</span><h3>${esc(section.name)}</h3><p>${esc(section.desc)}</p></div><span class="timeline-score">★ ${avg(fs)} / 10</span></div><div class="timeline-scroll"><div class="timeline-track">${fs.map((f,i)=>`<div class="timeline-stop ${i===0?'timeline-first':''}"><span class="timeline-node"></span><article class="timeline-film" data-film="${esc(f.id)}">${poster(f)}<div class="timeline-caption"><b>${esc(f.title)}</b><small>${f.year}</small></div></article></div>`).join('')}</div></div></section>`}).join('')}<section class="card"><h3>Cómo leer el mapa</h3><p><b>Godzilla (1954)</b> es el punto de partida de Shōwa y Heisei y un antecedente de varias continuidades Millennium. No todas las películas Millennium forman una sola historia: se muestran por separado cuando corresponde.</p><p>Las películas Reiwa tampoco comparten una única continuidad: Shin Godzilla, Minus One y la trilogía animada están separados. MonsterVerse y TriStar son universos propios.</p><p class="muted small">Este esquema agrupa las principales líneas de visionado; las conexiones más complejas se pueden ampliar en una futura versión.</p></section><h3>Las eras de producción</h3>${eras.map(e=>`<section class="era"><div><h3>${e[0]} <small>${e[1]}</small></h3><strong class="rating">★ ${avg(films.filter(f=>f.era===e[0]))} / 10</strong></div><p>${e[2]}</p></section>`).join('')}`}

else if(tab==='kaijus'){app.innerHTML=`<h2>ENCICLOPEDIA KAIJU</h2><p class="muted">Monstruos, apariciones y trajes o diseños cinematográficos.</p><input id="kaijufilter" placeholder="Buscar kaiju o tipo..."><div id="kaijugrid" class="kaiju-grid">${kaijus.map(kaijuCard).join('')}</div>`;document.getElementById('kaijufilter').oninput=e=>{const q=e.target.value.toLowerCase();document.getElementById('kaijugrid').innerHTML=kaijus.filter(k=>(k.name+' '+k.kind).toLowerCase().includes(q)).map(kaijuCard).join('');bindKaijus();hydrate()}}
else if(tab==='stats'){const scored=films.filter(f=>ratingNum(rec(f.id).score)!==null);const rated=scored.map(f=>rec(f.id).score);const favorites=films.filter(f=>rec(f.id).favorite);const watches=films.flatMap(f=>(rec(f.id).watches||[]).map(w=>({...w,film:f})));const decades=[...new Set(films.map(f=>Math.floor(f.year/10)*10))].sort();const top=scored.sort((a,b)=>rec(b.id).score-rec(a.id).score).slice(0,8);app.innerHTML=`<h2>MIS ESTADÍSTICAS</h2><p class="muted">Calculadas exclusivamente a partir de tus registros.</p><div class="stats"><div class="stat"><strong>${films.filter(f=>rec(f.id).watched).length}</strong><span>Vistas</span></div><div class="stat"><strong>${averageNumbers(rated)}</strong><span>Promedio</span></div><div class="stat"><strong>${watches.length}</strong><span>Visionados con fecha</span></div></div><h3>Promedios por era</h3><div class="bar-list">${eras.map(e=>{const fs=films.filter(f=>f.era===e[0]);const n=fs.filter(f=>ratingNum(rec(f.id).score)!==null).length;const a=avg(fs);return `<div class="bar-row"><div><b>${esc(e[0])}</b><span>${a}/10 · ${n} puntuadas · ${eraProgress(e[0]).seen}/${eraProgress(e[0]).total} vistas (${eraProgress(e[0]).percent}%)</span></div><div class="bar"><i style="width:${a==='—'?0:Number(a)*10}%"></i></div></div>`}).join('')}</div><h3>Promedios por década de estreno</h3><div class="bar-list">${decades.map(d=>{const fs=films.filter(f=>Math.floor(f.year/10)*10===d),a=avg(fs),n=fs.filter(f=>ratingNum(rec(f.id).score)!==null).length;return `<div class="bar-row"><div><b>${d}s</b><span>${a}/10 · ${n} puntuadas</span></div><div class="bar"><i style="width:${a==='—'?0:Number(a)*10}%"></i></div></div>`}).join('')}</div><h3>Mis películas mejor puntuadas</h3>${top.length?`<div class="grid">${top.map(card).join('')}</div>`:'<p class="muted">Puntúa algunas películas para ver tu clasificación.</p>'}<h3>Mis favoritas (${favorites.length})</h3>${favorites.length?`<div class="grid">${favorites.map(card).join('')}</div>`:'<p class="muted">Marca tus favoritas desde la ficha de cada película.</p>'}`}
else if(tab==='lists'){app.innerHTML=`<h2>MIS LISTAS</h2><p class="muted">Crea rankings, listas temáticas y colecciones personales. Puedes ordenarlas con los botones de subir y bajar.</p><section class="card register"><h3>Crear lista</h3><label for="listname">Nombre</label><input id="listname" maxlength="80" placeholder="Ej. Mis mejores diseños de Godzilla"><label for="listdesc">Descripción (opcional)</label><textarea id="listdesc" placeholder="¿Qué reúne esta lista?"></textarea><button class="primary" id="newlist">CREAR LISTA</button></section>${collections.map(c=>`<section class="card collection"><div class="collection-header"><div><h3>${esc(c.name)}</h3><p>${esc(c.desc||'')}</p><small>${c.films.length} películas</small></div><button class="secondary delete-list" data-list="${esc(c.id)}">Eliminar lista</button></div><label>Añadir película</label><div class="row"><select class="list-film" data-list="${esc(c.id)}"><option value="">Selecciona una película</option>${films.filter(f=>!c.films.includes(f.id)).map(f=>`<option value="${esc(f.id)}">${f.year} — ${esc(f.title)}</option>`).join('')}</select><button class="secondary add-list-film" data-list="${esc(c.id)}">AÑADIR</button></div><div class="list-entries">${c.films.map((id,i)=>{const f=films.find(f=>f.id===id);return f?`<div class="list-entry"><span class="list-rank">${i+1}</span><button class="list-open" data-film="${esc(id)}">${esc(f.title)} <small>(${f.year})</small></button><div class="list-controls"><button data-list="${esc(c.id)}" data-index="${i}" class="move-up" aria-label="Subir">↑</button><button data-list="${esc(c.id)}" data-index="${i}" class="move-down" aria-label="Bajar">↓</button><button data-list="${esc(c.id)}" data-index="${i}" class="remove-from-list" aria-label="Quitar">×</button></div></div>`:''}).join('')||'<p class="muted">Lista vacía.</p>'}</div></section>`).join('')}`;
document.getElementById('newlist').onclick=()=>{const name=document.getElementById('listname').value.trim();if(!name){alert('Escribe un nombre.');return}collections.push({id:'list-'+Date.now(),name,desc:document.getElementById('listdesc').value.trim(),films:[]});saveCollections();render()};
app.querySelectorAll('.delete-list').forEach(b=>b.onclick=()=>{if(!confirm('¿Eliminar esta lista?'))return;collections=collections.filter(c=>c.id!==b.dataset.list);saveCollections();render()});
app.querySelectorAll('.add-list-film').forEach(b=>b.onclick=()=>{const c=collections.find(c=>c.id===b.dataset.list);const id=app.querySelector(`.list-film[data-list="${b.dataset.list}"]`).value;if(c&&id&&!c.films.includes(id)){c.films.push(id);saveCollections();render()}});
for(const [selector,action] of [['.move-up',-1],['.move-down',1]])app.querySelectorAll(selector).forEach(b=>b.onclick=()=>{const c=collections.find(c=>c.id===b.dataset.list),i=Number(b.dataset.index),j=i+action;if(c&&j>=0&&j<c.films.length){[c.films[i],c.films[j]]=[c.films[j],c.films[i]];saveCollections();render()}});
app.querySelectorAll('.remove-from-list').forEach(b=>b.onclick=()=>{const c=collections.find(c=>c.id===b.dataset.list);if(c){c.films.splice(Number(b.dataset.index),1);saveCollections();render()}});
}
else if(tab==='admin'){app.innerHTML=`<h2>ADMINISTRAR CATÁLOGO</h2><p>Agrega películas y kaijus sin modificar el código. Los cambios se guardan en este navegador; exporta una copia de seguridad.</p><section class="card register"><h3>Nueva película</h3><label>Título</label><input id="newtitle" placeholder="Título"><label>Año</label><input id="newyear" type="number" min="1954" max="2200"><label>Era</label><select id="newera">${[...eras.map(x=>x[0])].map(x=>`<option>${esc(x)}</option>`).join('')}</select><label>Sinopsis</label><textarea id="newdesc"></textarea><button class="primary" id="addfilm">AGREGAR PELÍCULA</button></section><section class="card register"><h3>Nuevo kaiju / individuo</h3><label>Nombre</label><input id="newkname" placeholder="Nombre de esta encarnación"><label>Tipo</label><input id="newkind" placeholder="Ej. reptil gigante"><label>Descripción</label><textarea id="newkdesc"></textarea><button class="primary" id="addkaiju">AGREGAR KAIJU</button></section><section class="card register"><h3>Editar fichas</h3><p>Selecciona una película para editar su sinopsis, dirección, continuidad y kaijus (IDs separados por comas).</p><select id="editfilm">${films.map(f=>`<option value="${esc(f.id)}">${f.year} — ${esc(f.title)}</option>`).join('')}</select><label>Dirección</label><input id="editdirector"><label>Sinopsis</label><textarea id="editdesc"></textarea><label>Continuidad</label><input id="editcontinuity"><label>IDs de kaijus</label><input id="editkaijus"><p class="muted small">IDs disponibles: ${kaijus.map(k=>esc(k.id)).join(', ')}</p><button class="primary" id="saveedit">GUARDAR CAMBIOS</button></section>`;
const ed=document.getElementById('editfilm');function fill(){const f=films.find(x=>x.id===ed.value);document.getElementById('editdirector').value=f.director||'';document.getElementById('editdesc').value=f.desc||'';document.getElementById('editcontinuity').value=f.continuity||'';document.getElementById('editkaijus').value=(f.kaiju||[]).join(', ')}ed.onchange=fill;fill();
document.getElementById('addfilm').onclick=()=>{const title=document.getElementById('newtitle').value.trim(),year=Number(document.getElementById('newyear').value);if(!title||!Number.isInteger(year)||year<1954||year>2200){alert('Escribe título y año válido');return}const f={id:'custom-'+Date.now(),title,year,era:document.getElementById('newera').value,director:'Por documentar',desc:document.getElementById('newdesc').value,continuity:'Por documentar',kaiju:[]};additions.films.push(f);films.push(f);saveCatalog();render();alert('Película agregada')};
document.getElementById('addkaiju').onclick=()=>{const name=document.getElementById('newkname').value.trim();if(!name){alert('Escribe el nombre');return}const k={id:'kaiju-'+Date.now(),name,kind:document.getElementById('newkind').value,desc:document.getElementById('newkdesc').value,films:[],outside:[],suits:[]};additions.kaijus.push(k);kaijus.push(k);saveCatalog();render();alert('Kaiju agregado')};
document.getElementById('saveedit').onclick=()=>{const id=ed.value;const patch={director:document.getElementById('editdirector').value,desc:document.getElementById('editdesc').value,continuity:document.getElementById('editcontinuity').value,kaiju:document.getElementById('editkaijus').value.split(',').map(x=>x.trim()).filter(x=>kaijus.some(k=>k.id===x))};additions.edits[id]=patch;Object.assign(films.find(f=>f.id===id),patch);saveCatalog();alert('Ficha actualizada')};}
else if(tab==='diary'){const logged=films.filter(f=>rec(f.id).watched||rec(f.id).score!==undefined||rec(f.id).review||rec(f.id).favorite||(rec(f.id).watches||[]).length);app.innerHTML=`<h2>MI DIARIO</h2>${logged.length?`<div class="grid">${logged.map(card).join('')}</div>`:'<p>Todavía no has registrado películas.</p>'}<section class="card backup"><h3>Respaldo completo</h3><p>Exporta puntuaciones, reseñas, favoritos, historial, listas, cambios del catálogo <b>y todas tus fotografías añadidas manualmente</b>. Las fotografías externas de internet no se descargan en el respaldo. El archivo puede ser grande si has añadido muchas imágenes.</p><div class="row"><button class="primary" id="export">EXPORTAR TODO</button><button class="secondary" id="import">IMPORTAR RESPALDO</button><input type="file" accept="application/json,.json" id="backup" hidden></div><p class="muted small">Para migrar al teléfono, exporta desde el navegador anterior e importa el archivo en la instalación nueva. No borres los datos originales hasta comprobar la importación.</p></section>`;document.getElementById('export').onclick=exportBackup;document.getElementById('import').onclick=()=>document.getElementById('backup').click();document.getElementById('backup').onchange=e=>importBackup(e.target.files?.[0])}

bindFilms();bindKaijus();attachUploads();hydrate().then(()=>{hydrateHeroFromSuit();hydrateKaijuPhotos();hydrateSuitPhotos()});hydrateOutside();hydrateActorPhotos()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;selected=null;selectedKaiju=null;render()});render();if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
